SELECT 
FROM public.attributes
WHERE game_id = #{gameId}

    AND (
        strpos(lower(attribute_key), lower(#{keyword})) > 0
        OR strpos(lower(name), lower(#{keyword})) > 0
    )


    AND status = #{status}

ORDER BY sort_order ASC, name ASC, attribute_key ASC

SELECT 
FROM public.attributes
WHERE game_id = #{gameId}
  AND attribute_key = #{attributeKey}

SELECT 
FROM public.attributes
WHERE game_id = #{gameId}
  AND attribute_key = #{attributeKey}
FOR UPDATE

SELECT COUNT(1)
FROM public.attributes
WHERE game_id = #{gameId}
  AND attribute_key = #{attributeKey}

SELECT COUNT(1)
FROM public.attributes
WHERE game_id = #{gameId}
  AND lower(btrim(name)) = lower(btrim(#{name}))

  AND attribute_key <> #{excludeAttributeKey}
